def pluck(arr):
    even_nodes = [(val, idx) for idx, val in enumerate(arr) if val % 2 == 0]
    if not even_nodes:
        return []
    return min(even_nodes, key=lambda x: (x[0], x[1]))

# Test cases
print(pluck([4, 2, 3]))  # Output: [2, 1]
print(pluck([1, 2, 3]))  # Output: [2, 1]
print(pluck([]))  # Output: []
print(pluck([5, 0, 3, 0, 4, 2]))  # Output: [0, 1]

def search(lst):
    # Create a dictionary to store the frequency of each number
    freq = {}
    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Find the greatest number that is greater than zero and has a frequency greater than or equal to the value of the integer itself
    max_num = -1
    for num in sorted(freq.keys(), reverse=True):
        if num > 0 and freq[num] >= num:
            max_num = num
            break

    return max_num

# Test cases
print(search([4, 1, 2, 2, 3, 1]))  # == 2
print(search([1, 2, 2, 3, 3, 3, 4, 4, 4]))  # == 3
print(search([5, 5, 4, 4, 4]))  # == -1

def search(lst):
    # Create a dictionary to store the frequency of each integer
    freq = {}
    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the result as -1
    result = -1

    # Iterate over the dictionary in descending order of keys
    for key in sorted(freq, reverse=True):
        # If the frequency of the current integer is greater than or equal to the integer itself
        if freq[key] >= key:
            # Update the result
            result = key
            # Break the loop as we have found the greatest integer
            break

    return result

