def smallest_change(arr):
    n = len(arr)
    # Create a frequency dictionary to store the count of each element
    freq = {}
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the count of elements that need to be changed
    changes = 0
    # Iterate over the frequency dictionary
    for count in freq.values():
        # If the count is odd, it means we need to change the middle element
        # So, we add the count minus 1 to the changes
        if count % 2 != 0:
            changes += count - 1

    return changes

