def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        if x in row:
            result.append((i, row[::-1].index(x)))
    return sorted(result, key=lambda x: (x[0], -x[1]))

def sort_array(array):
    if len(array) == 0:
        return array

    if (array[0] + array[-1]) % 2 == 0:
        return sorted(array, reverse=True)
    else:
        return sorted(array)

