def encode(message):
    vowels = 'aeiouAEIOU'
    result = ''
    for char in message:
        if char in vowels:
            new_char = chr(ord(char) + 2)
            result += new_char
        elif char.isalpha():
            new_char = char.swapcase()
            result += new_char
        else:
            result += char
    return result

