def match_parens(lst):
    def is_good(s):
        balance = 0
        for c in s:
            if c == '(':
                balance += 1
            elif c == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    for s in [''.join(lst), ''.join(reversed(lst))]:
        if is_good(s):
            return 'Yes'
    return 'No'

