def do_algebra(operator, operand):
    # Check if the length of operator list is equal to the length of operand list minus one
    if len(operator) != len(operand) - 1:
        raise ValueError("The length of operator list must be equal to the length of operand list minus one.")

    # Check if the operand list has at least two operands
    if len(operand) < 2:
        raise ValueError("The operand list must have at least two operands.")

    # Check if the operand list contains non-negative integers
    if not all(isinstance(x, int) and x >= 0 for x in operand):
        raise ValueError("The operand list must contain non-negative integers.")

    # Initialize the result with the first operand
    result = operand[0]

    # Iterate over the operator and operand lists
    for i in range(len(operator)):
        # Apply the current operator to the result and the next operand
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]

    return result

